package com.locallaunch.controller;
import com.locallaunch.dto.*; import com.locallaunch.entity.ContactEnquiry; import com.locallaunch.service.ContactEnquiryService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/enquiries") public class ContactEnquiryController { private final ContactEnquiryService service; public ContactEnquiryController(ContactEnquiryService s){service=s;} @PostMapping("/public/{businessId}") public ResponseEntity<ContactEnquiry> create(@PathVariable Long businessId,@Valid @RequestBody ContactEnquiry e){return ResponseEntity.ok(service.saveEnquiry(businessId,e));} @GetMapping("/my/{businessId}") public List<ContactEnquiryDTO> mine(@PathVariable Long businessId){return service.getMyEnquiries(businessId);} @PutMapping("/{id}/status") public ContactEnquiryDTO status(@PathVariable Long id,@Valid @RequestBody EnquiryStatusRequest r){return service.updateEnquiryStatus(id,r);} @DeleteMapping("/{id}") public ResponseEntity<String> delete(@PathVariable Long id){service.deleteEnquiry(id);return ResponseEntity.ok("Enquiry deleted successfully");} }
